# Permission modes as the composer lists them (MODES in web/src/components/Composer.tsx).
MODES = [
    {
        "id": "default",
        "label": "Ask before edits",
        "hint": "Asks before changing files or running commands",
        "icon": "shield-check",
    },
    {
        "id": "acceptEdits",
        "label": "Edit automatically",
        "hint": "File edits are applied without asking",
        "icon": "file-pen",
    },
    {"id": "plan", "label": "Plan mode", "hint": "Explores and proposes a plan; changes nothing", "icon": "map"},
    {"id": "auto", "label": "Auto", "hint": "Approves routine actions, asks about risky ones", "icon": "zap"},
    {
        "id": "bypassPermissions",
        "label": "Bypass permissions",
        "hint": "Runs everything without asking — sandboxes only",
        "icon": "shield-off",
    },
]


@dataclass
class Cmd:
    id: str
    label: str
    icon: str
    group: str  # "Actions" | "Sessions" | "Files"
    run: Callable[[], None]
    hint: str = ""
    kbd: str = ""


class PalItem(QWidget):
    """One row of the list (``.pal-item``): icon, label, hint, keys."""

    entered = Signal()
    chosen = Signal()

    def __init__(self, cmd: Cmd, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.cmd = cmd
        self._active = False
        self.setFixedHeight(36)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        self.setAccessibleName(cmd.label)
        lay = QHBoxLayout(self)
        lay.setContentsMargins(10, 0, 10, 0)
        lay.setSpacing(11)
        self.ico = QLabel()
        lay.addWidget(self.ico)
        self.label = QLabel(cmd.label)
        lay.addWidget(self.label)
        self.hint = ElideLabel(cmd.hint)
        self.hint.setProperty("size", "small")
        lay.addWidget(self.hint, 1)
        if not cmd.hint:
            self.hint.hide()
            lay.addStretch(1)
        if cmd.kbd:
            lay.addWidget(Keys(cmd.kbd, quiet=True))
        self._paint()

    def set_active(self, on: bool) -> None:
        if on != self._active:
            self._active = on
            self._paint()

    def _paint(self) -> None:
        t = theme.tokens()
        on = self._active
        self.setStyleSheet(
            f"PalItem {{ background: {theme.blend(t.fill_2, t.canvas).name() if on else 'transparent'}; border-radius: {theme.R2}px; }}"
        )
        self.ico.setPixmap(icons.pixmap(self.cmd.icon, t.text if on else t.text_3, 14))
        self.label.setStyleSheet(f"color: {t.text if on else t.text_2};")
        self.hint.setStyleSheet(f"color: {t.text_3}; font-size: {theme.FS_SMALL}px;")

    def enterEvent(self, e) -> None:  # noqa: N802
        self.entered.emit()
        super().enterEvent(e)

    def mouseReleaseEvent(self, e) -> None:  # noqa: N802
        if e.button() == Qt.MouseButton.LeftButton:
            self.chosen.emit()


class CommandPalette(Sheet):
    def __init__(self, window: QWidget) -> None:
