        usage = task.get("usage") or {}
        if int(usage.get("total_tokens") or 0) > 0:
            foot.addWidget(label(f"{tokens(int(usage['total_tokens']))} tokens", tone="faint", size="micro"))
        foot.addStretch(1)
        if live:
