  if (!cache.has(sid)) cache.set(sid, readJson(stepsFile(cwd, sid), []));
  return cache.get(sid);
}

function saveSteps(cwd, sid, steps) {
  cache.set(sid, steps);
  writeJson(stepsFile(cwd, sid), steps);
