  const wt = await sg(cwd, ['write-tree']);
  if (wt.code !== 0) return null;
  const tree = wt.stdout.trim();
  const steps = loadSteps(cwd, sid);
  const last = steps[steps.length - 1];
  let commit = last?.commit || null;
  let files = [];
