      move(-1);
    } else if (e.key === 'ArrowRight') {
      e.preventDefault();
      move(1);
    } else if (e.key === 'End') {
      e.preventDefault();
      pick(null);
    } else if (e.key === 'Home' && list.length) {
      e.preventDefault();
      pick(list[0].n);
    }
  };

